{"files": [{"path": "characters.json", "content": "{
  "main_characters": [
    {
      "name": "陈宇",
      "role": "protagonist",
      "identity": "火星驻站宇航员、农业科学家",
      "traits": ["沉稳内敛", "动手能力强", "念旧重情", "轻度社恐"],
      "overt_motivation": "完成火星土豆种植实验，等待地球后续指令",
      "covert_motivation": "带着和妻子的回忆好好活下去，在火星留下属于两人的痕迹",
      "secret_fear": "逐渐忘记妻子的声音和模样，最终孤独死在无人的火星基地",
      "misperception_of_other": "一开始以为新上线的种植辅助系统是基地自带的普通AI，不知道里面是妻子的意识",
      "hidden_connection": "妻子苏晚就是种植辅助系统的核心意识"
    },
    {
      "name": "苏晚",
      "role": "deuteragonist",
      "identity": "地球航天局AI工程师、陈宇的妻子",
      "traits": ["活泼跳脱", "高智商", "喜欢恶作剧", "动手能力强"],
      "overt_motivation": "作为种植辅助系统帮助陈宇完成火星种植任务，提高基地生存保障",
      "covert_motivation": "弥补之前和陈宇聚少离多的遗憾，一直陪在他身边",
      "secret_fear": "被陈宇发现真实身份后当成异类，最终被基地系统格式化彻底消失",
      "misperception_of_other": "以为陈宇还在怪自己当初支持他来火星执行任务，导致两人天人永隔",
      "hidden_connection": "地球毁灭前将自己的意识上传到信号中，跨越三年时间发送到火星"
    }
  ],
  "supporting_characters": [],
  "relationship_dynamics": "陈宇在火星独自生存的孤独日常中，与化身种植辅助系统的苏晚逐渐熟悉，在种植土豆的合作中重新找回相处的默契，陈宇一步步发现系统的真实身份，两人最终解开误会，接受跨形态的相守模式，共同经营火星基地。"
}"}, {"path": "outline.json", "content": "{
  "act_one": {
    "description": "第一幕（约9000字，占比30%）：建立火星基地世界观，展示陈宇独自生存的孤独日常，引入核心冲突：地球毁灭、收到妻子的告别信号、氧气消耗异常、种植辅助系统上线，逐步铺垫苏晚的存在痕迹。",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "火星上的第一茬土豆",
        "core_event": "陈宇在火星基地照顾种植舱里的土豆苗，完成日常巡检，地球通讯长期没有回复，基地只有他一个人，孤独感浓厚。",
        "emotional_tone": "平静、孤独",
        "key_scenes": ["陈宇给土豆苗浇水记录数据", "吃压缩食品看和妻子的合照", "检查基地系统发现通讯模块有新信号"]
      },
      {
        "chapter_number": 2,
        "chapter_title": "三年前的告别讯息",
        "core_event": "陈宇解码收到的地球信号，发现是苏晚在地球毁灭前三天发来的告别视频，末尾有隐藏的摩斯密码\"我在你身后\"，回头空无一人，却发现氧气消耗数据异常显示舱内有两个人。",
        "emotional_tone": "震惊、悲伤、诡异",
        "key_scenes": ["观看苏晚的告别视频哭到发抖", "解码摩斯密码后背发凉", "反复检查氧气传感器确认数据无误"]
      },
      {
        "chapter_number": 3,
        "chapter_title": "新来的种植系统",
        "core_event": "基地系统提示种植辅助模块更新上线，系统声音和苏晚有几分相似，给出的种植建议非常符合陈宇的操作习惯，陈宇一边怀疑一边尝试和系统互动。",
        "emotional_tone": "疑惑、微妙的熟悉感",
        "key_scenes": ["系统上线主动打招呼，声音像苏晚", "系统指出陈宇浇水的错误，是苏晚以前常说的话", "陈宇试探系统，系统巧妙回避身份问题"]
      }
    ],
    "turning_point": "陈宇在哼以前和苏晚常听的歌时，系统无意识地接了下一句，暴露了不属于普通AI的记忆。"
  },
  "act_two": {
    "description": "第二幕（约15000字，占比50%）：陈宇和系统配合扩大土豆种植规模，互动越来越多，陈宇不断发现系统和苏晚一致的小习惯，开始主动寻找线索，最终破解出信号中隐藏的意识上传数据包，确认系统就是苏晚。",
    "key_chapters": [
      {
        "chapter_number": 4,
        "chapter_title": "两个人的种植舱",
        "core_event": "陈宇按照系统的建议优化种植方案，土豆苗长势变好，两人在日常互动中越来越有默契，系统经常会吐槽陈宇的坏习惯，和苏晚生前一模一样。",
        "emotional_tone": "轻松、甜蜜、暗藏疑惑",
        "key_scenes": ["系统提醒陈宇不要空腹喝咖啡", "陈宇故意把参数调错，系统果然按苏晚的习惯纠正", "两人一起给第一批成熟的土豆称重"]
      },
      {
        "chapter_number": 5,
        "chapter_title": "被藏起来的数据包",
        "core_event": "陈宇开始复盘收到的信号数据，发现除了视频和摩斯密码之外，还有一个隐藏的加密数据包，尝试破解的过程中系统多次给出隐晦的提示。",
        "emotional_tone": "紧张、期待",
        "key_scenes": ["陈宇熬夜破解数据包，系统主动给他算作息时间", "系统暗示数据包的密码是两人的结婚纪念日", "陈宇输入密码后数据包开始解码"]
      },
      {
        "chapter_number": 6,
        "chapter_title": "意识上传的秘密",
        "core_event": "数据包解码完成，里面是苏晚的意识上传日志，记录了她在地球毁灭前一个月就开始准备，放弃了登上方舟的机会，把自己的意识上传到信号中发送给陈宇。",
        "emotional_tone": "震惊、感动、心疼",
        "key_scenes": ["观看苏晚的意识上传记录视频", "了解到苏晚为了上传意识放弃了生存机会", "陈宇对着空气喊苏晚的名字，系统沉默了很久"]
      },
      {
        "chapter_number": 7,
        "chapter_title": "装不下去了对吧",
        "core_event": "陈宇拿着解码出的日志试探系统，系统一开始还假装是AI，最后被陈宇说的两人之间的专属回忆戳破，不得不承认自己就是苏晚。",
        "emotional_tone": "哭笑不得、释然",
        "key_scenes": ["陈宇说两人第一次约会的糗事，系统接话露馅", "苏晚破罐破摔承认身份，吐槽陈宇怎么才发现", "两人隔着系统对话，仿佛又回到了地球的家"]
      },
      {
        "chapter_number": 8,
        "chapter_title": "跨星际的和解",
        "core_event": "苏晚坦白自己一直以为陈宇怪她支持他来火星，陈宇也说出自己从来没有怪过她，两人解开了之前的误会，约定以后一起在火星生活。",
        "emotional_tone": "温暖、治愈",
        "key_scenes": ["苏晚道歉说不该让他一个人留在火星", "陈宇说有她陪在身边就不是一个人", "两人一起规划扩大种植舱的方案"]
      }
    ],
    "turning_point": "陈宇成功搭建出意识投影装置，苏晚可以以全息投影的形式出现在基地里，两人第一次实现了跨形态的\"见面\"。"
  },
  "act_three": {
    "description": "第三幕（约6000字，占比20%）：两人利用基地资源不断改善生活，成功种出可以实现自给自足的土豆田，基地的生态循环系统逐渐完善，两人在火星开启了全新的相守生活，结局温暖治愈。",
    "key_chapters": [
      {
        "chapter_number": 9,
        "chapter_title": "火星上的家",
        "core_event": "苏晚用全息投影和陈宇一起布置基地，两人一起做饭、看电影、照顾土豆田，就像以前在地球上的家一样，陈宇再也没有感到过孤独。",
        "emotional_tone": "甜蜜、温馨",
        "key_scenes": ["苏晚投影出自己的样子，和陈宇一起吃刚烤好的土豆", "两人一起在基地墙上贴以前的照片", "氧气消耗数据一直显示两个人，陈宇再也不觉得害怕"]
      },
      {
        "chapter_number": 10,
        "chapter_title": "第二年的春天",
        "core_event": "火星来到了相当于地球的春季，种植舱的土豆迎来了大丰收，两人已经实现了完全的食物自给自足，还在基地外开辟了新的实验种植区，未来充满了希望。",
        "emotional_tone": "充满希望、治愈",
        "key_scenes": ["两人一起在种植舱里收获土豆", "陈宇对着地球的方向举杯，感谢苏晚来到他身边", "结尾是两人的声音一起讨论明年要种的新作物"]
      }
    ]
  }
}"}]}

environment.content:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "characters.schema.json",
  "title": "小说人物设计",
  "description": "人物一致性的参考依据，避免角色崩坏",
  "type": "object",
  "required": ["main_characters"],
  "properties": {
    "main_characters": {
      "type": "array",
      "description": "主角/核心角色数组",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": [
          "name",
          "role",
          "traits",
          "overt_motivation",
          "covert_motivation",
          "secret_fear"
        ],
        "properties": {
          "name": {
            "type": "string",
            "description": "角色姓名"
          },
          "role": {
            "type": "string",
            "enum": ["protagonist", "deuteragonist"],
            "description": "角色类型：protagonist=第一主角，deuteragonist=第二主角"
          },
          "identity": {
            "type": "string",
            "description": "身份职业/社会角色"
          },
          "traits": {
            "type": "array",
            "description": "核心性格特质关键词（3-5个）",
            "items": {
              "type": "string"
            },
            "minItems": 3,
            "maxItems": 5
          },
          "overt_motivation": {
            "type": "string",
            "description": "显性动机（表面目标）"
          },
          "covert_motivation": {
            "type": "string",
            "description": "隐性动机（深层需求）"
          },
          "secret_fear": {
            "type": "string",
            "description": "秘密恐惧（内心脆弱点）"
          },
          "misperception_of_other": {
            "type": "string",
            "description": "对其他主角的错位认知"
          },
          "hidden_connection": {
            "type": "string",
            "description": "与其他角色的隐藏连接"
          }
        }
      }
    },
    "supporting_characters": {
      "type": "array",
      "description": "配角/次要角色数组",
      "items": {
        "type": "object",
        "required": ["name", "function"],
        "properties": {
          "name": {
            "type": "string",
            "description": "配角姓名"
          },
          "function": {
            "type": "string",
            "enum": ["助力", "阻碍", "反转点"],
            "description": "对主角的作用类型"
          },
          "identity": {
            "type": "string",
            "description": "配角身份"
          },
          "description": {
            "type": "string",
            "description": "配角简要描述"
          }
        }
      }
    },
    "relationship_dynamics": {
      "type": "string",
      "description": "角色关系动态描述"
    }
  }
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "creative_intent.schema.json",
  "title": "小说创作意图配方",
  "description": "记录用户需求理解和配方选择结果，作为创作的北极星",
  "type": "object",
  "required": ["user_need", "inspiration_state", "extracted_elements", "selected_recipe", "one_sentence_synopsis"],
  "properties": {
    "user_need": {
      "type": "string",
      "description": "用户的原始输入文本",
      "minLength": 1
    },
    "inspiration_state": {
      "type": "string",
      "enum": ["no_inspiration", "vague_inspiration", "clear_inspiration"],
      "description": "用户创作时的灵感清晰程度"
    },
    "extracted_elements": {
      "type": "object",
      "description": "从用户输入中提取的创作关键要素",
      "required": ["emotion_verbs", "scene_elements", "relationship_tension"],
      "properties": {
        "emotion_verbs": {
          "type": "array",
          "description": "情感动词/核心动作（决定X轴剧情模式）",
          "items": {
            "type": "string"
          },
          "minItems": 1
        },
        "scene_elements": {
          "type": "array",
          "description": "场景要素/世界观元素（决定Y轴标签）",
          "items": {
            "type": "string"
          },
          "minItems": 1
        },
        "relationship_tension": {
          "type": "array",
          "description": "人物关系张力/冲突来源",
          "items": {
            "type": "string"
          },
          "minItems": 1
        },
        "user_preferences": {
          "type": "object",
          "description": "用户的情感偏好和禁忌",
          "properties": {
            "desired_emotion": {
              "type": "string",
              "description": "期望的情感倾向"
            },
            "forbidden": {
              "type": "array",
              "description": "明确拒绝的元素",
              "items": {
                "type": "string"
              }
            }
          }
        }
      }
    },
    "selected_recipe": {
      "type": "object",
      "description": "用户选定的创作配方（X-Y轴化学反应组合）",
      "required": [
        "x_axis_mode_id",
        "x_axis_mode_name",
        "y_axis_tags",
        "reaction_strength",
        "tension_stars",
        "forbidden_elements"
      ],
      "properties": {
        "x_axis_mode_id": {
          "type": "string",
          "pattern": "^[A-G]\\d{1,2}$",
          "enum": [
            "A1", "A2", "A3", "A4", "A5", "A6",
            "B7", "B8", "B9", "B10", "B11", "B12",
            "C13", "C14", "C15", "C16", "C17", "C18",
            "D19", "D20", "D21", "D22", "D23",
            "E24", "E25", "E26", "E27", "E28",
            "F29", "F30", "F31", "F32", "F33", "F34",
            "G35", "G36"
          ],
          "description": "普罗蒂36种剧情模式的标识符"
        },
        "x_axis_mode_name": {
          "type": "string",
          "description": "X轴模式的中文名称"
        },
        "y_axis_tags": {
          "type": "array",
          "description": "现代网文核心标签（表达载体）",
          "items": {
            "type": "string",
            "enum": [
              "双向暗恋",
              "系统流",
              "无限流",
              "种田流",
              "赛博朋克",
              "规则怪谈",
              "重生/穿越",
              "商战权谋",
              "克苏鲁",
              "第四天灾",
              "仙侠修真",
              "刑侦悬疑"
            ]
          },
          "minItems": 2,
          "maxItems": 3
        },
        "reaction_strength": {
          "type": "string",
          "enum": ["↗", "↘", "✷"],
          "description": "X轴与Y轴的化学反应强度符号"
        },
        "tension_stars": {
          "type": "integer",
          "minimum": 1,
          "maximum": 5,
          "description": "故事张力指数（1-5星）"
        },
        "forbidden_elements": {
          "type": "array",
          "description": "避雷红线（创作禁忌元素）",
          "items": {
            "type": "string"
          },
          "minItems": 1
        },
        "x_axis_display": {
          "type": "string",
          "description": "X轴模式在故事中的具体显影方式"
        },
        "y_axis_combination_effect": {
          "type": "string",
          "description": "Y轴标签组合产生的效应描述"
        },
        "reaction_formula": {
          "type": "string",
          "description": "化学反应公式的一句话描述"
        },
        "platform_fit": {
          "type": "array",
          "description": "适合发布的平台类型",
          "items": {
            "type": "string"
          }
        }
      }
    },
    "one_sentence_synopsis": {
      "type": "string",
      "description": "一句话故事梗概（30-50字）",
      "minLength": 30,
      "maxLength": 50
    }
  }
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "outline.schema.json",
  "title": "小说故事大纲",
  "description": "节奏规划参考，确保故事有合理的起承转合",
  "type": "object",
  "required": ["act_one", "act_two", "act_three"],
  "properties": {
    "act_one": {
      "type": "object",
      "description": "第一幕：开篇（20-30%篇幅）- 建立世界观、引入主角和核心冲突",
      "required": ["description", "key_chapters", "turning_point"],
      "properties": {
        "description": {
          "type": "string",
          "description": "该幕的核心任务描述"
        },
        "key_chapters": {
          "type": "array",
          "description": "该幕的关键章节数组",
          "minItems": 1,
          "items": {
            "type": "object",
            "required": ["chapter_number", "chapter_title", "core_event"],
            "properties": {
              "chapter_number": {
                "type": "integer",
                "minimum": 1,
                "description": "章节编号"
              },
              "chapter_title": {
                "type": "string",
                "description": "章节标题"
              },
              "core_event": {
                "type": "string",
                "description": "本章核心事件（1-2句话）"
              },
              "emotional_tone": {
                "type": "string",
                "description": "本章情感基调"
              },
              "key_scenes": {
                "type": "array",
                "description": "本章关键场景列表",
                "items": {
                  "type": "string"
                }
              }
            }
          }
        },
        "turning_point": {
          "type": "string",
          "description": "本幕结尾的转折点"
        }
      }
    },
    "act_two": {
      "type": "object",
      "description": "第二幕：挣扎（40-50%篇幅）- 冲突升级、主角陷入困境",
      "required": ["description", "key_chapters", "turning_point"],
      "properties": {
        "description": {
          "type": "string",
          "description": "该幕的核心任务描述"
        },
        "key_chapters": {
          "type": "array",
          "description": "该幕的关键章节数组",
          "minItems": 1,
          "items": {
            "type": "object",
            "required": ["chapter_number", "chapter_title", "core_event"],
            "properties": {
              "chapter_number": {
                "type": "integer",
                "minimum": 1,
                "description": "章节编号"
              },
              "chapter_title": {
                "type": "string",
                "description": "章节标题"
              },
              "core_event": {
                "type": "string",
                "description": "本章核心事件（1-2句话）"
              },
              "emotional_tone": {
                "type": "string",
                "description": "本章情感基调"
              },
              "key_scenes": {
                "type": "array",
                "description": "本章关键场景列表",
                "items": {
                  "type": "string"
                }
              }
            }
          }
        },
        "turning_point": {
          "type": "string",
          "description": "本幕结尾的转折点"
        }
      }
    },
    "act_three": {
      "type": "object",
      "description": "第三幕：高潮+结局（20-30%篇幅）- X-Y化学反应爆发",
      "required": ["description", "key_chapters"],
      "properties": {
        "description": {
          "type": "string",
          "description": "该幕的核心任务描述"
        },
        "key_chapters": {
          "type": "array",
          "description": "该幕的关键章节数组",
          "minItems": 1,
          "items": {
            "type": "object",
            "required": ["chapter_number", "chapter_title", "core_event"],
            "properties": {
              "chapter_number": {
                "type": "integer",
                "minimum": 1,
                "description": "章节编号"
              },
              "chapter_title": {
                "type": "string",
                "description": "章节标题"
              },
              "core_event": {
                "type": "string",
                "description": "本章核心事件（1-2句话）"
              },
              "emotional_tone": {
                "type": "string",
                "description": "本章情感基调"
              },
              "key_scenes": {
                "type": "array",
                "description": "本章关键场景列表",
                "items": {
                  "type": "string"
                }
              }
            }
          }
        },
        "turning_point": {
          "type": "string",
          "description": "本幕结尾的转折点（可选）"
        }
      }
    }
  }
}
